// fake gateway (signed calls must stop at signing: there is no signer). Every stream checks its
// required selector fields before connecting.
// Both encodings: in lite the fake gateway also fails on any request key that is not a lite name.
func TestEveryRPCIsReachable(t *testing.T) {
	for _, enc := range encodings {
		t.Run(enc.String(), func(t *testing.T) { everyRPCIsReachable(t, enc) })
	}
}

